"use client"

import { useState, useEffect } from "react"
import { Header } from "@/components/header"
import { Footer } from "@/components/footer"
import { Card, CardContent } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Badge } from "@/components/ui/badge"
import { Search, SlidersHorizontal, MapPin, Zap, Check, Star, TrendingUp, Loader2, Globe2 } from "lucide-react"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"

export default function PlansPage() {
  const [selectedCountry, setSelectedCountry] = useState(null)
  const [searchQuery, setSearchQuery] = useState("")
  const [sortBy, setSortBy] = useState("popular")
  const [filterRegion, setFilterRegion] = useState("all")
  const [countries, setCountries] = useState([])
  const [plans, setPlans] = useState([])
  const [loadingCountries, setLoadingCountries] = useState(true)
  const [loadingPlans, setLoadingPlans] = useState(false)

  useEffect(() => {
    fetchCountries()
  }, [])

  useEffect(() => {
    if (selectedCountry) {
      fetchPlans(selectedCountry.code)
    }
  }, [selectedCountry])

  async function fetchCountries() {
    try {
      setLoadingCountries(true)
      const response = await fetch("/api/v1/countries?active=true")
      const data = await response.json()

      if (data.success) {
        setCountries(data.countries)
      }
    } catch (error) {
      console.error("Failed to fetch countries:", error)
    } finally {
      setLoadingCountries(false)
    }
  }

  async function fetchPlans(countryCode) {
    try {
      setLoadingPlans(true)
      const response = await fetch(`/api/v1/plans?country=${countryCode}`)
      const data = await response.json()

      if (data.success) {
        setPlans(data.plans)
      }
    } catch (error) {
      console.error("Failed to fetch plans:", error)
    } finally {
      setLoadingPlans(false)
    }
  }

  const filteredCountries = countries.filter((country) => {
    const matchesSearch = country.name.toLowerCase().includes(searchQuery.toLowerCase())
    const matchesRegion = filterRegion === "all" || country.region === filterRegion
    return matchesSearch && matchesRegion
  })

  const popularCountries = countries.filter((c) => c.popular).slice(0, 6)
  const uniqueRegions = [...new Set(countries.map((c) => c.region))].sort()

  const sortedPlans = [...plans].sort((a, b) => {
    switch (sortBy) {
      case "price-low":
        return a.price - b.price
      case "price-high":
        return b.price - a.price
      case "data":
        return (b.dataGB || 0) - (a.dataGB || 0)
      default:
        return (b.salesCount || 0) - (a.salesCount || 0)
    }
  })

  return (
    <div className="min-h-screen bg-background">
      <Header />

      <main className="pt-20">
        {/* Hero Section */}
        <section className="relative bg-gradient-to-br from-emerald-50 via-white to-blue-50 dark:from-emerald-950/20 dark:via-background dark:to-blue-950/20 py-20 lg:py-28 overflow-hidden">
          {/* Animated background elements */}
          <div className="absolute inset-0 overflow-hidden pointer-events-none">
            <div className="absolute top-20 left-10 w-72 h-72 bg-emerald-200/30 dark:bg-emerald-600/10 rounded-full blur-3xl animate-pulse" />
            <div className="absolute bottom-20 right-10 w-96 h-96 bg-blue-200/30 dark:bg-blue-600/10 rounded-full blur-3xl animate-pulse delay-1000" />
          </div>

          <div className="container mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
            <div className="max-w-4xl mx-auto text-center space-y-8 animate-fade-in">
              <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-300 text-sm font-medium mb-4 animate-slide-in-top">
                <Globe2 className="h-4 w-4" />
                <span>190+ Countries Available</span>
              </div>

              <h1 className="text-5xl sm:text-6xl lg:text-7xl font-bold text-balance leading-tight">
                Find Your{" "}
                <span className="bg-gradient-to-r from-emerald-600 to-blue-600 dark:from-emerald-400 dark:to-blue-400 bg-clip-text text-transparent animate-gradient">
                  Perfect Data Plan
                </span>
              </h1>

              <p className="text-xl text-muted-foreground text-pretty max-w-2xl mx-auto leading-relaxed">
                Stay connected anywhere in the world with instant eSIM activation. No physical SIM cards, no hassle.
              </p>

              <div className="flex flex-wrap items-center justify-center gap-6 pt-4">
                <div className="flex items-center gap-2">
                  <Check className="h-5 w-5 text-emerald-600 dark:text-emerald-400" />
                  <span className="text-sm font-medium">Instant Activation</span>
                </div>
                <div className="flex items-center gap-2">
                  <Check className="h-5 w-5 text-emerald-600 dark:text-emerald-400" />
                  <span className="text-sm font-medium">No Contracts</span>
                </div>
                <div className="flex items-center gap-2">
                  <Check className="h-5 w-5 text-emerald-600 dark:text-emerald-400" />
                  <span className="text-sm font-medium">24/7 Support</span>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* Main Content */}
        <section className="py-16 lg:py-20">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <div className="grid lg:grid-cols-3 gap-8">
              {/* Left Sidebar - Country Selection */}
              <div className="lg:col-span-1 space-y-6">
                <Card className="sticky top-24 shadow-xl border-border/50 backdrop-blur-sm">
                  <CardContent className="p-6 space-y-6">
                    {/* Search */}
                    <div className="space-y-2">
                      <label className="text-sm font-semibold flex items-center gap-2">
                        <Search className="h-4 w-4 text-emerald-600" />
                        Search Country
                      </label>
                      <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                        <Input
                          type="text"
                          placeholder="e.g. United States"
                          value={searchQuery}
                          onChange={(e) => setSearchQuery(e.target.value)}
                          className="pl-10 bg-background/50"
                        />
                      </div>
                    </div>

                    {/* Region Filter */}
                    <div className="space-y-2">
                      <label className="text-sm font-semibold flex items-center gap-2">
                        <MapPin className="h-4 w-4 text-blue-600" />
                        Filter by Region
                      </label>
                      <Select value={filterRegion} onValueChange={setFilterRegion}>
                        <SelectTrigger className="bg-background/50">
                          <SelectValue placeholder="All Regions" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="all">All Regions</SelectItem>
                          {uniqueRegions.map((region) => (
                            <SelectItem key={region} value={region}>
                              {region}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>

                    {loadingCountries ? (
                      <div className="flex items-center justify-center py-12">
                        <Loader2 className="h-8 w-8 animate-spin text-emerald-600" />
                      </div>
                    ) : (
                      <>
                        {/* Popular Countries */}
                        {popularCountries.length > 0 && (
                          <div className="space-y-3">
                            <div className="flex items-center gap-2">
                              <Star className="h-4 w-4 text-amber-500 fill-amber-500" />
                              <span className="text-sm font-semibold">Popular Destinations</span>
                            </div>
                            <div className="space-y-2">
                              {popularCountries.map((country) => (
                                <button
                                  key={country._id}
                                  onClick={() => setSelectedCountry(country)}
                                  className={`w-full flex items-center gap-3 p-3 rounded-xl border-2 transition-all duration-300 ${
                                    selectedCountry?._id === country._id
                                      ? "bg-gradient-to-r from-emerald-50 to-blue-50 dark:from-emerald-950/50 dark:to-blue-950/50 border-emerald-500 shadow-lg scale-105"
                                      : "bg-card border-border/50 hover:bg-secondary hover:border-emerald-300 dark:hover:border-emerald-700 hover:scale-102"
                                  }`}
                                >
                                  <span className="text-3xl">{country.flag || "🌍"}</span>
                                  <div className="flex-1 text-left">
                                    <div className="text-sm font-semibold">{country.name}</div>
                                    <div className="text-xs text-muted-foreground">{country.region}</div>
                                  </div>
                                  {selectedCountry?._id === country._id && (
                                    <Check className="h-5 w-5 text-emerald-600 dark:text-emerald-400 animate-scale-in" />
                                  )}
                                </button>
                              ))}
                            </div>
                          </div>
                        )}

                        {/* All Countries */}
                        {filteredCountries.length > 0 && (
                          <div className="space-y-3">
                            <div className="flex items-center gap-2">
                              <Globe2 className="h-4 w-4 text-emerald-600" />
                              <span className="text-sm font-semibold">All Countries ({filteredCountries.length})</span>
                            </div>
                            <div className="space-y-2 max-h-[400px] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-emerald-200 dark:scrollbar-thumb-emerald-800">
                              {filteredCountries.map((country) => (
                                <button
                                  key={country._id}
                                  onClick={() => setSelectedCountry(country)}
                                  className={`w-full flex items-center gap-3 p-2.5 rounded-lg border transition-all text-sm ${
                                    selectedCountry?._id === country._id
                                      ? "bg-emerald-50 dark:bg-emerald-950/50 border-emerald-500"
                                      : "bg-card border-border/50 hover:bg-secondary hover:border-emerald-300 dark:hover:border-emerald-700"
                                  }`}
                                >
                                  <span className="text-xl">{country.flag || "🌍"}</span>
                                  <span className="flex-1 text-left font-medium">{country.name}</span>
                                  {selectedCountry?._id === country._id && (
                                    <Check className="h-4 w-4 text-emerald-600 dark:text-emerald-400" />
                                  )}
                                </button>
                              ))}
                            </div>
                          </div>
                        )}
                      </>
                    )}
                  </CardContent>
                </Card>
              </div>

              {/* Right Content - Data Plans */}
              <div className="lg:col-span-2 space-y-6">
                {/* Sort & Filter Bar */}
                <Card className="shadow-lg border-border/50">
                  <CardContent className="p-4">
                    <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                      <div className="flex items-center gap-3">
                        <SlidersHorizontal className="h-5 w-5 text-emerald-600" />
                        <span className="text-sm font-semibold">
                          {selectedCountry ? (
                            <>
                              <span className="text-2xl mr-2">{selectedCountry.flag || "🌍"}</span>
                              Plans for {selectedCountry.name}
                            </>
                          ) : (
                            "Select a country to view plans"
                          )}
                        </span>
                      </div>
                      {selectedCountry && (
                        <Select value={sortBy} onValueChange={setSortBy}>
                          <SelectTrigger className="w-[200px]">
                            <SelectValue placeholder="Sort by" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="popular">Most Popular</SelectItem>
                            <SelectItem value="price-low">Price: Low to High</SelectItem>
                            <SelectItem value="price-high">Price: High to Low</SelectItem>
                            <SelectItem value="data">Data Amount</SelectItem>
                          </SelectContent>
                        </Select>
                      )}
                    </div>
                  </CardContent>
                </Card>

                {/* Plans List */}
                {!selectedCountry ? (
                  <Card className="shadow-lg border-border/50">
                    <CardContent className="p-16 text-center">
                      <div className="max-w-md mx-auto space-y-6 animate-fade-in">
                        <div className="relative mx-auto w-24 h-24">
                          <div className="absolute inset-0 bg-gradient-to-br from-emerald-400 to-blue-500 rounded-full opacity-20 animate-pulse" />
                          <div className="relative h-full w-full rounded-full bg-gradient-to-br from-emerald-50 to-blue-50 dark:from-emerald-950/50 dark:to-blue-950/50 flex items-center justify-center">
                            <Globe2 className="h-12 w-12 text-emerald-600 dark:text-emerald-400" />
                          </div>
                        </div>
                        <h3 className="text-2xl font-bold">Select a Country</h3>
                        <p className="text-muted-foreground leading-relaxed">
                          Choose your destination from the list to discover available data plans and pricing options
                        </p>
                      </div>
                    </CardContent>
                  </Card>
                ) : loadingPlans ? (
                  <Card className="shadow-lg border-border/50">
                    <CardContent className="p-16 text-center">
                      <div className="space-y-4">
                        <Loader2 className="h-12 w-12 animate-spin text-emerald-600 mx-auto" />
                        <p className="text-muted-foreground">Loading plans for {selectedCountry.name}...</p>
                      </div>
                    </CardContent>
                  </Card>
                ) : sortedPlans.length === 0 ? (
                  <Card className="shadow-lg border-border/50">
                    <CardContent className="p-16 text-center">
                      <div className="max-w-md mx-auto space-y-4">
                        <div className="h-20 w-20 rounded-full bg-gray-100 dark:bg-gray-800 flex items-center justify-center mx-auto">
                          <MapPin className="h-10 w-10 text-gray-400" />
                        </div>
                        <h3 className="text-xl font-semibold">No Plans Available</h3>
                        <p className="text-muted-foreground">
                          We don't have any plans for {selectedCountry.name} yet. Check back soon!
                        </p>
                      </div>
                    </CardContent>
                  </Card>
                ) : (
                  <div className="space-y-4">
                    {sortedPlans.map((plan, index) => (
                      <Card
                        key={plan._id}
                        className="group hover:shadow-2xl transition-all duration-500 hover:-translate-y-2 border-border/50 overflow-hidden animate-slide-in-bottom"
                        style={{ animationDelay: `${index * 100}ms` }}
                      >
                        <div className="absolute inset-0 bg-gradient-to-r from-emerald-500/5 to-blue-500/5 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />

                        <CardContent className="p-6 relative">
                          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                            {/* Plan Details */}
                            <div className="flex-1 space-y-4">
                              <div className="flex items-start justify-between gap-4">
                                <div className="space-y-3">
                                  <div className="flex items-center gap-3 flex-wrap">
                                    <h3 className="text-3xl font-bold bg-gradient-to-r from-emerald-600 to-blue-600 dark:from-emerald-400 dark:to-blue-400 bg-clip-text text-transparent">
                                      {plan.isUnlimited ? "Unlimited" : `${plan.dataGB} GB`}
                                    </h3>
                                    {plan.salesCount > 100 && (
                                      <Badge className="bg-gradient-to-r from-emerald-500 to-blue-500 text-white border-0">
                                        <TrendingUp className="h-3 w-3 mr-1" />
                                        Best Seller
                                      </Badge>
                                    )}
                                  </div>
                                  <h4 className="text-lg font-semibold text-foreground">{plan.name}</h4>
                                  <div className="flex items-center gap-4 text-sm text-muted-foreground flex-wrap">
                                    <span className="flex items-center gap-1">
                                      <Zap className="h-4 w-4 text-emerald-600" />
                                      Valid for {plan.validityDays} days
                                    </span>
                                    <span>•</span>
                                    <span>High-speed 4G/5G</span>
                                  </div>
                                </div>
                                <div className="text-right">
                                  <div className="text-4xl font-bold text-emerald-600 dark:text-emerald-400">
                                    ${plan.price.toFixed(2)}
                                  </div>
                                  <div className="text-xs text-muted-foreground mt-1">{plan.currency}</div>
                                </div>
                              </div>

                              {/* Features */}
                              <div className="flex flex-wrap gap-2">
                                <Badge
                                  variant="secondary"
                                  className="gap-1 bg-emerald-50 dark:bg-emerald-950/50 text-emerald-700 dark:text-emerald-300"
                                >
                                  <Zap className="h-3 w-3" />
                                  Instant Activation
                                </Badge>
                                <Badge
                                  variant="secondary"
                                  className="gap-1 bg-blue-50 dark:bg-blue-950/50 text-blue-700 dark:text-blue-300"
                                >
                                  <Check className="h-3 w-3" />
                                  No Contract
                                </Badge>
                                <Badge
                                  variant="secondary"
                                  className="gap-1 bg-amber-50 dark:bg-amber-950/50 text-amber-700 dark:text-amber-300"
                                >
                                  <Star className="h-3 w-3 fill-current" />
                                  Premium Support
                                </Badge>
                              </div>
                            </div>

                            {/* CTA */}
                            <div className="lg:w-48">
                              <Button
                                size="lg"
                                className="w-full bg-gradient-to-r from-emerald-600 to-blue-600 hover:from-emerald-700 hover:to-blue-700 text-white shadow-lg hover:shadow-xl transition-all duration-300 group/btn"
                              >
                                <span>Buy Now</span>
                                <Check className="ml-2 h-5 w-5 group-hover/btn:scale-110 transition-transform" />
                              </Button>
                              <p className="text-xs text-center text-muted-foreground mt-2">Delivery in seconds</p>
                            </div>
                          </div>
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>
        </section>
      </main>

      <Footer />
    </div>
  )
}
